SELECT price FROM drug_price 
WHERE drug_id = #{drugId} 
  AND price_type = #{priceType} 
  AND effective_date <= #{date}
  AND (expire_date IS NULL OR expire_date > #{date})
ORDER BY effective_date DESC
LIMIT 1

